var CONTEXT_ENGINE_TURN_OUTBOX_TABLE;
var init_openclaw_agent_context_engine_turn_outbox_schema = __esmMin((() => {
	init_sqlite_transaction();
	CONTEXT_ENGINE_TURN_OUTBOX_TABLE = "context_engine_turn_outbox";
}));
